"""Regenerates src/main/kotlin/.../SoundData.kt from sounds/*.ogg.

Plugin zips carry only manifest.json, index.js and plugin.jar, so the sounds ride inside the code
as base64. A Kotlin string constant is capped at 65535 bytes, so each file is split into chunks.

Run from the plugin folder:  python tools/embed_sounds.py
"""
import base64
import pathlib

HERE = pathlib.Path(__file__).resolve().parent.parent
OUT = HERE / "src/main/kotlin/com/bleelblep/sparkle/SoundData.kt"
CHUNK = 60000

lines = [
    "// GENERATED by tools/embed_sounds.py from sounds/*.ogg -- do not edit by hand.",
    "// Sources and licences: sounds/LICENSE.txt.",
    "",
    "package com.bleelblep.sparkle",
    "",
    "internal object SoundData {",
    "\t/** File name -> base64 chunks, joined in order. */",
    "\tval files: Map<String, Array<String>> = mapOf(",
]
for path in sorted((HERE / "sounds").glob("*.ogg")):
    data = base64.b64encode(path.read_bytes()).decode("ascii")
    chunks = [data[i : i + CHUNK] for i in range(0, len(data), CHUNK)]
    body = ", ".join(f'"{c}"' for c in chunks)
    lines.append(f'\t\t"{path.name}" to arrayOf({body}),')
lines += ["\t)", "}", ""]
OUT.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {OUT.name}: {OUT.stat().st_size} bytes")
